            background-color: white; 
            border-radius: 5px; 
            padding: 20px; 
            display: flex; 
            justify-content: space-around; 
            align-items: center; 
            width: 60%; 
        }
        .team { 
            display: flex; 
            flex-direction: column; 
            align-items: center; 
        }
