            width: 200px; 
            height: 200px; 
            margin-bottom: 10px; 
            border-radius: 50%; 
        }
        .team button { 
            background-color: #008CBA; 
            border: none; 
            color: white; 
            padding: 10px 20px; 
            text-align: center; 
            text-decoration: none; 
