function [fig, best_fit, details] = regression(xval, yval, m)

% Initializing details structure array
details(1).model = 'linear';
details(2).model = 'non-linear';

% Linear model
rmse_linear = zeros(m, 1);
coef_linear = cell(m, 1);

for i = 1:m
    p = polyfit(xval, yval, i);
    yfit = polyval(p, xval);
    rmse_linear(i) = sqrt(mean((yval - yfit).^2));
    coef_linear{i} = p;
end

details(1).order = 1:m;
details(1).coefs = coef_linear;
details(1).RMSE = rmse_linear;

% Non-linear model
logyval = log(yval);
p = polyfit(xval, logyval, 1);
c = exp(p(2));
b = p(1);
yfit = c * exp(b * xval);
rmse_nonlinear = sqrt(mean((yval - yfit).^2));

details(2).order = 'n/a';
details(2).coefs = [c, b];
details(2).RMSE = rmse_nonlinear;

% RMSE comparison
[min_rmse_linear, min_lin_idx] = min(rmse_linear);
if min_rmse_linear < rmse_nonlinear
    best_fit = sprintf('linear-%d', min_lin_idx);
else
    best_fit = 'non-linear';
end

% Plotting
fig = figure;

xvals = linspace(min(xval), max(xval), 50); 
axis([min(xval) max(xval) min(yval) max(yval)])

hold on;
% Plot raw data
plot(xval, yval, 'k*');

% Plot linear models
for i = 1:m
    yfit = polyval(coef_linear{i}, xvals);
    plot(xvals, yfit, '-');
end

% Plot non-linear model
yfit = c * exp(b * xvals);
plot(xvals, yfit, '-');

hold off;

end

