def is_prime(num):
    if num == 1:
        return False
    for i in range(2, int(num**0.5) + 1):
        if num % i == 0:
            return False
    return True

def closest_prime(num):
    if is_prime(num):
        return num
    lower = num - 1
    upper = num + 1
    while not is_prime(lower) and not is_prime(upper):
        lower -= 1
        upper += 1
    if is_prime(lower):
        return lower
    else:
        return upper

