            }
            return valuesList.GetEnumerator();
        }

        public IEnumerator<K> Keys()
        {
            List<K> keysList = new List<K>();

            for (int i = 0; i < this.Capacity; i++)
            {
                Entry<K, V> entry = this.Table[i];

                if (entry != null && entry.Value != null)
