    for (int i = 0; i < n; i++) {
        B[i] = (i % 2 ? 1 : -1) * A[i];
    }

    // Start of the Kadane's Algorithm Logic
    vector<int> dp(n);
    vector<int> start_indices(n);
    dp[0] = B[0];
    start_indices[0] = 1;
    int max_val = dp[0];
