    top: 0;
    left: 50%;
    transform: translateX(-50%);
    background-color: rgba(0, 0, 0, 0.5);
    padding: 5px 15px;
    margin: 10px;
    border-radius: 5px;
    display: inline-flex;
    align-items: center;
}

.label {
    color: #ffffff;
    font-family: Arial, sans-serif;
    font-size: 14px;
}

.score {
    color: #247c24;
    font-family: Arial, sans-serif;
    font-size: 14px;
    font-weight: bold;
    margin-left: 5px;
}
```

Now, only the scoreboard will be visible with a transparent background, and the rest of the screen will be empty.

